-- Suppliers (worker/src/supplier.mjs): which supplier to choose for a product, with the evidence. One scorecard per
-- product, opened from the Launch view. The method behind it: docs/sourcing/supplier-selection.md.
-- product_key: a launch card's key, as launches saves it ('eu|…', 'world|…', 'tiktok|…'), or 'own|<slug>' for a product
-- added by name. facts: JSON, the product when the scorecard started (title, link, photo, its price there).
-- setup: JSON, your choices for this product: target market, the most days a customer waits, the weights, your price,
-- units per order, the sample tests, the questions for suppliers, the certificates it needs (defaults in supplierKit).
-- checks: JSON {"shortlist": true, ...}, the process checklist. suppliers: JSON {"s1": {...}, ..., "s5": {...}}, up to 5.
-- choice: JSON {"current": {...} | null, "past": [...]}, your decision record (the supplier as it was then, a backup,
-- why, the date, the next re-check) and the ones before it.
CREATE TABLE IF NOT EXISTS sourcing (
  product_key TEXT PRIMARY KEY,
  title TEXT,
  facts TEXT,
  setup TEXT,
  checks TEXT,
  suppliers TEXT,
  choice TEXT,
  created_at TEXT,
  updated_at TEXT
);
-- The first product: the filtered showerhead Connor found at a competitor (muravai.com) and on 1688. Only its setup is
-- seeded (sample tests, questions, certificates): no suppliers, those are his to fill in. Seeded once: the state row says
-- it was, so a scorecard removed on the board does not come back when the migrations run again (every workflow run).
INSERT OR IGNORE INTO sourcing (product_key, title, facts, setup, checks, suppliers, choice, created_at, updated_at)
